from src.serializer import User, serialize, deserialize


def test_user_to_dict():
    u = User(name="Alice", age=30)
    d = u.to_dict()
    assert d == {"name": "Alice", "age": 30}


def test_user_from_dict():
    u = User.from_dict({"name": "Bob", "age": 25})
    assert u.name == "Bob"
    assert u.age == 25


def test_serialize():
    u = User(name="Carol", age=22)
    assert serialize(u) == {"name": "Carol", "age": 22}


def test_deserialize():
    u = deserialize(User, {"name": "Dave", "age": 40})
    assert isinstance(u, User)
    assert u.name == "Dave"


def test_roundtrip():
    original = User(name="Eve", age=35)
    restored = User.from_dict(original.to_dict())
    assert restored.name == original.name
    assert restored.age == original.age

